def chain_follows_chain(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = b
        else:
            chain_dict[a] = chain_dict[b]

    chain_list = []
    current = 'gfr'
    while current not in chain_dict:
        chain_list.append(current)
        current = chain_dict[current]

    return ','.join(chain_list)

# Example usage:
# print(chain_follows_chain(['gfr', 'lhr']))  # Output: 'gfr,lhr'
